import{R as t,e as a,f as n,U as s}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Stencils","description":"","frontmatter":{},"headers":[],"relativePath":"forms/stencils.md","filePath":"forms/stencils.md","lastUpdated":1775908585000}'),i={name:"forms/stencils.md"};function o(r,e,l,c,d,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="stencils" tabindex="-1">Stencils <a class="header-anchor" href="#stencils" aria-label="Permalink to &quot;Stencils&quot;">​</a></h1><p>Stencils are reusable starter forms.</p><p>They are useful when you want a faster, more consistent starting point than building every new form from scratch. A stencil can carry the same kinds of structure and setup you would normally define on a form, including fields and layout, pages, notifications, and form settings.</p><p>That means a stencil is more than a visual starting point. It can carry real behavior with it as well.</p><h2 id="when-to-use-stencils" tabindex="-1">When to use stencils <a class="header-anchor" href="#when-to-use-stencils" aria-label="Permalink to &quot;When to use stencils&quot;">​</a></h2><p>Stencils are especially helpful when:</p><ul><li>a team creates the same kinds of forms repeatedly</li><li>clients need a safe starting point</li><li>you want to keep common patterns consistent across projects</li></ul><p>Formie includes a default <code>Contact Form</code> stencil as a general starting point, and you can create your own when you need something more specific.</p><h2 id="creating-and-using-stencils" tabindex="-1">Creating and using stencils <a class="header-anchor" href="#creating-and-using-stencils" aria-label="Permalink to &quot;Creating and using stencils&quot;">​</a></h2><p>You can create and manage stencils in <code>Formie → Settings → Stencils</code>. Building a stencil works much like building a normal form, so you can define the layout, notifications, and form settings you want to reuse.</p><p>Once a stencil exists, it becomes an option when creating a new form. Choosing a stencil gives you a quick starting point, and from there the form becomes its own form that can be changed independently.</p><h2 id="shared-starting-points" tabindex="-1">Shared starting points <a class="header-anchor" href="#shared-starting-points" aria-label="Permalink to &quot;Shared starting points&quot;">​</a></h2><p>Stencils are best treated as starting templates, not shared live forms. Changes made to a stencil affect future forms created from it, not forms that already exist.</p><p>Stencils are also stored in project config, which makes them useful for keeping standard starting points available across environments and across a team.</p>',14)])])}const p=t(i,[["render",o]]);export{u as __pageData,p as default};
